## Code Example

```cpp
// simplified per-node free-list CAS skeleton
#include <atomic>

struct Node {
  std::atomic<void*> head{nullptr};
};

void* alloc(Node& node) {
  void* h = node.head.load(std::memory_order_acquire);
  if (h) {
    void* next = *(void**)h;
    if (node.head.compare_exchange_weak(h, next, std::memory_order_acquire, std::memory_order_relaxed))
      return h;
  }
  // fallback: steal from other node or central pool
  return nullptr;
}
```

